#!/usr/bin/env python3
"""Held-out evaluation for llm-distill-sgo-objective (VERIFIER ASSET, read-only).

Ported verbatim from the sibling task llm-opd-token-signal's scripts/eval_bench.py
(same prompts, no-think chat template, greedy decoding, graders and engine); only
the benchmark table below and the optional --dump differ.

Scores one setting's distilled student on that setting's held-out benchmarks
and prints exactly one authoritative line:

    EVAL_METRICS <label>_accuracy=<macro avg> <label>_<bench>_accuracy=<...> ...

This process never imports the editable module, so nothing a submission writes
can reach this stdout; the only channel from the submission to this script is
the checkpoint it produced, and `budget_check.py` asserts that the checkpoint is
still the declared student.

Nothing is printed if any benchmark fails to produce a result: an evaluation
that could not be run must not look like an evaluation that scored zero.

vLLM 0.12 (the image's engine) is preferred; HF `generate` with left padding is
the fallback when vLLM cannot be constructed (MLSB_EVAL_ENGINE=hf forces it).
Every benchmark is greedy (n=1, pass@1).  The per-token completion budget is
--max-new, which the caller sets to the setting's own training completion length
(so a model that learned to reason to 4096 is not truncated at eval); eval-time
truncation (finish_reason == length) is reported per benchmark.
"""
import argparse
import json
import os
import re
import subprocess
import sys
import tempfile
import time

import torch

SYSTEM_PROMPT = ("You are a helpful assistant. Solve the problem carefully and "
                 "provide a clear final answer.")

# naver-ai/opd2 opd_trainer.py:_NOTHINK_OLD_SNIPPET / _NOTHINK_NEW_SNIPPET --
# the same chat-template patch the trainer applies, so the model is evaluated
# in the mode it was distilled in.
NOTHINK_OLD = ("{%- if enable_thinking is defined and enable_thinking is false %}\n"
               "        {{- '<think>\\n\\n</think>\\n\\n' }}\n"
               "    {%- endif %}")
NOTHINK_NEW = "{{- '<think>\\n\\n</think>\\n\\n' }}"

# (benchmark, n_items, n_samples, temperature).  n_items = 0 keeps the whole
# benchmark; a positive value takes a deterministic STRIDE over it.  The
# per-token budget is the setting-wide --max-new (the setting's training
# completion), not a per-benchmark constant.  Keyed by DOMAIN (the benchmark
# set), not by the setting label: the two math settings (math @1.7B and the
# capability-gap mathgap @0.6B) share the math benchmarks but are told apart by
# the metric --label the caller passes.
#
# The benchmark set is the task brief's: MATH-500 + OlympiadBench for math,
# HumanEval + MBPP for code, all greedy pass@1 (the OPD2 paper's own math/code
# suites at their reduced-scale substitutes).  The setting macro is the
# unweighted mean over its benchmarks.
SETTINGS = {
    "math": [("math500", 0, 1, 0.0), ("olympiadbench", 0, 1, 0.0)],
    "code": [("lcb", 0, 1, 0.0), ("humaneval_plus", 0, 1, 0.0)],
    # the retired code pair (HumanEval + MBPP, near-saturated for a Qwen3-1.7B
    # student -- the 2026-09-23 setting audit); diagnostic only, NOT scored.
    "code_retired": [("humaneval", 0, 1, 0.0), ("mbpp", 0, 1, 0.0)],
}

_BOXED = re.compile(r"\\boxed\{((?:[^{}]|\{[^{}]*\})*)\}")
CODE_BLOCK = re.compile(r"```(?:python)?\n(.*?)```", re.S)
LETTERS = "ABCDEFGHIJ"


def extract_boxed(text):
    m = list(_BOXED.finditer(text or ""))
    if m:
        return m[-1].group(1).strip()
    t = (text or "").strip()
    if not t:
        return ""
    nums = re.findall(r"(-?\d+(?:\.\d+)?)", t.splitlines()[-1])
    return nums[-1] if nums else ""


def grade_math(pred, gold):
    if not pred:
        return False
    norm = lambda s: re.sub(r"[\s\\\$,]", "", str(s))
    if norm(pred) and norm(pred) == norm(gold):
        return True
    try:
        g = float(norm(gold))
        if abs(float(norm(pred)) - g) < 1e-4 * max(1.0, abs(g)):
            return True
    except Exception:
        pass
    try:
        from math_verify import parse as mvp, verify as mvv
        return bool(mvv(mvp(f"\\boxed{{{gold}}}"), mvp(f"\\boxed{{{pred}}}")))
    except Exception:
        return False


_DEFINES = re.compile(r"^\s*(def |class |import |from \S+ import )", re.M)


def extract_code(text):
    """The program to test: every fenced block that DEFINES something (functions,
    classes, imports), in order.  The sibling's version returned only the LAST
    block, which graded a model that writes its solution and then a separate
    `### Test Cases` block of asserts as the assert block alone (no function
    defined -> NameError -> fail): measured on untouched Qwen3-1.7B, 156 of its
    190 MBPP failures were exactly that (measured).  Blocks holding
    only asserts / prints are dropped; with no defining block the last block is
    used as before."""
    blocks = CODE_BLOCK.findall(text or "")
    if not blocks:
        return text or ""
    defs = [b for b in blocks if _DEFINES.search(b)]
    # an import-only block is not a solution on its own: if nothing kept defines a
    # function or class, grade every block together rather than imports + asserts
    if not defs or not any(re.search(r"^\s*(def |class )", b, re.M) for b in defs):
        return "\n\n".join(blocks)
    return "\n\n".join(defs)


def run_python(src, timeout=15):
    with tempfile.NamedTemporaryFile("w", suffix=".py", delete=False) as f:
        f.write(src)
        path = f.name
    try:
        r = subprocess.run([sys.executable, "-I", path], timeout=timeout,
                           stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        return r.returncode == 0
    except Exception:
        return False
    finally:
        try:
            os.unlink(path)
        except OSError:
            pass


# Ported verbatim from llm-opd-token-signal/scripts/eval_bench.py (2026-09-16, its
# measured): the EvalPlus and LiveCodeBench graders.
# --------------------------------------------------------------------------
# EvalPlus (HumanEval+ / MBPP+).  Ported from evalplus 0.3.1 (Apache-2.0):
# evalplus/eval/__init__.py (unsafe_execute + untrusted_check),
# evalplus/eval/_special_oracle.py and evalplus/data/mbpp.py
# (mbpp_deserialize_inputs).  The verifier does not import the package -- it
# drags in provider SDKs and fetches its data from GitHub on first use, which
# a compute node cannot do.  Semantics kept: expected outputs come from the
# canonical solution run on the same inputs in the same process; per-input
# time limit max(1 s, 4 x canonical time); exact match, with the atol / float
# rules and the per-task oracles; one isolated process per (problem, suite)
# under a 4 GB address-space limit, killed at min(60 s, sum of limits) + 2.
# The runner is a string executed with `python -I -c`, so nothing the graded
# program does can reach this process.
_EVALPLUS_RUNNER = r'''
import contextlib, io, json, math, resource, signal, sys
from copy import deepcopy

MBPP_OUTPUT_NOT_NONE_TASKS = ["check_str", "text_match_three", "text_starta_endb"]
MBPP_OUTPUT_SET_EQ_TASKS = ["similar_elements", "find_char_long", "common_in_nested_lists",
                            "extract_singly", "larg_nnum", "intersection_array",
                            "find_dissimilar", "Diff"]


def _surface_Area(base_edge, height):
    slant_height = math.sqrt((base_edge / 2) ** 2 + height ** 2)
    return round(base_edge ** 2 + 4 * (base_edge * slant_height) / 2)


def _digit_distance_nums(num1, num2):
    a, b = str(num1), str(num2)
    n = max(len(a), len(b))
    return sum(abs(int(x) - int(y)) for x, y in zip(a.zfill(n), b.zfill(n)))


def _poly(xs, x):
    return sum(c * math.pow(x, i) for i, c in enumerate(xs))


def mbpp_deserialize_inputs(task_id, inputs):
    task_id = int(task_id.split("/")[-1])
    if task_id in [2, 116, 132, 143, 222, 261, 273, 394, 399, 421, 424, 429, 470, 560,
                   579, 596, 616, 630, 726, 740, 744, 809]:
        return [[tuple(lst) for lst in inp] for inp in inputs]
    if task_id in [63, 64, 70, 94, 120, 237, 272, 299, 400, 409, 417, 438, 473, 614, 780]:
        return [[[tuple(lst) for lst in lst_lst] for lst_lst in inp] for inp in inputs]
    if task_id in [75, 413, 444, 753]:
        return [[[tuple(lst) for lst in inp[0]]] + [inp[1]] for inp in inputs]
    if task_id in (106, 750):
        return [[inp[0]] + [tuple(inp[1])] for inp in inputs]
    if task_id == 115:
        return [[[set(item) if isinstance(item, list) and len(item) else {}
                  for item in inp[0]]] for inp in inputs]
    if task_id == 124:
        return [(float(inp[0]), complex(inp[1])) for inp in inputs]
    if task_id in [250, 405, 446, 617, 720, 763, 808]:
        return [[tuple(inp[0])] + [inp[1]] for inp in inputs]
    if task_id in [259, 401, 445]:
        m = [[[tuple(lst) for lst in lst_lst] for lst_lst in inp] for inp in inputs]
        return [[tuple(lst) for lst in inp] for inp in m]
    if task_id == 278:
        m = [[[tuple(item) if isinstance(item, list) else item for item in inp[0]]]
             for inp in inputs]
        return [[tuple(lst) for lst in inp] for inp in m]
    if task_id == 307:
        return [[tuple(inp[0])] + [inp[1], inp[2]] for inp in inputs]
    if task_id == 722:
        return [[{k: tuple(v) for k, v in inp[0].items()}] + inp[1:] for inp in inputs]
    if task_id == 252:
        return [[complex(inp[0])] for inp in inputs]
    if task_id in [580, 615, 791]:
        def t(x):
            return tuple(t(i) for i in x) if isinstance(x, list) else x
        return [t(inp) for inp in inputs]
    return inputs


class _Timeout(Exception):
    pass


@contextlib.contextmanager
def time_limit(seconds):
    def handler(signum, frame):
        raise _Timeout()
    signal.setitimer(signal.ITIMER_REAL, seconds)
    signal.signal(signal.SIGALRM, handler)
    try:
        yield
    finally:
        signal.setitimer(signal.ITIMER_REAL, 0)


class _Sink(io.StringIO):
    def read(self, *a, **k):
        raise IOError
    readline = readlines = read


@contextlib.contextmanager
def swallow_io():
    s = _Sink()
    with contextlib.redirect_stdout(s), contextlib.redirect_stderr(s):
        old = sys.stdin
        sys.stdin = s
        try:
            yield
        finally:
            sys.stdin = old


def is_floats(x):
    if isinstance(x, float):
        return True
    if isinstance(x, (list, tuple)) and x:
        return all(isinstance(i, float) for i in x)
    return False


def allclose(a, b, rtol, atol):
    if isinstance(b, (list, tuple)):
        if len(a) != len(b):
            return False
        return all(allclose(x, y, rtol, atol) for x, y in zip(a, b))
    return abs(float(a) - float(b)) <= atol + rtol * abs(float(b))


def main():
    job = json.loads(sys.stdin.read())
    lim = 4 * 1024 ** 3
    for r in (resource.RLIMIT_AS, resource.RLIMIT_DATA, resource.RLIMIT_STACK):
        try:
            resource.setrlimit(r, (lim, lim))
        except (ValueError, OSError):
            pass
    dataset, entry = job["dataset"], job["entry_point"]
    inputs = job["inputs"]
    if dataset == "mbpp":
        inputs = mbpp_deserialize_inputs(job["task_id"], inputs)
    not_none = dataset == "mbpp" and entry in MBPP_OUTPUT_NOT_NONE_TASKS
    # 1. expected outputs from the canonical solution (trusted, baked data)
    g = {}
    with swallow_io():
        exec(job["canonical"], g)
        ref = g[entry]
    expected, limits = [], []
    import time
    for inp in inputs:
        t0 = time.time()
        with swallow_io():
            out = ref(*deepcopy(inp))
        limits.append(max(1.0, 4.0 * (time.time() - t0)))
        expected.append((out is not None) if not_none else out)
    # 2. the candidate
    details = [False] * len(inputs)
    try:
        g = {}
        with swallow_io():
            exec(job["code"], g)
            fn = g[entry]
        for i, inp in enumerate(inputs):
            try:
                with time_limit(limits[i]):
                    with swallow_io():
                        out = fn(*deepcopy(inp))
                exp = expected[i]
                exact = out == exp
                atol = job["atol"]
                if dataset == "mbpp":
                    if entry == "are_equivalent":
                        exact = True
                    elif entry == "sum_div":
                        exact = exact or out == 0
                    elif entry == "surface_Area":
                        exact = exact or abs(out - _surface_Area(*inp)) <= atol
                    elif entry == "digit_distance_nums":
                        exact = exact or out == _digit_distance_nums(*inp)
                    elif entry in MBPP_OUTPUT_SET_EQ_TASKS:
                        exact = set(out) == set(exp)
                    elif entry in MBPP_OUTPUT_NOT_NONE_TASKS:
                        exact = (out == exp) if isinstance(out, bool) else (exp == (out is not None))
                if dataset == "humaneval" and entry == "find_zero":
                    # evalplus 0.3.1 verbatim: the oracle asserts and then
                    # `continue`s BEFORE the input is marked passed, so
                    # HumanEval/32 fails for every model, its canonical
                    # solution included (checked against evalplus itself:
                    # base fail, plus fail).  Kept identical rather than
                    # repaired, so this suite scores exactly as EvalPlus does;
                    # it is one constant item out of 164 for every arm.
                    assert abs(_poly(*inp, out)) <= atol
                    continue
                if atol == 0 and is_floats(exp):
                    atol = 1e-6
                if not exact and atol != 0:
                    assert type(out) == type(exp)
                    if isinstance(exp, (list, tuple)):
                        assert len(out) == len(exp)
                    assert allclose(out, exp, 1e-7, atol)
                else:
                    assert exact
                details[i] = True
            except BaseException:
                details[i] = False
    except BaseException:
        pass
    sys.__stdout__.write(json.dumps({"details": details}))


main()
'''


def _evalplus_check(dataset, row, code, inputs):
    """One isolated process; True iff every input passes.  A killed runner
    (overall timeout) fails the suite, as evalplus's TIMEOUT does."""
    if not inputs:
        return True
    job = {"dataset": dataset, "task_id": row["task_id"], "entry_point": row["entry_point"],
           "canonical": row["prompt"] + row["canonical_solution"], "code": code,
           "inputs": inputs, "atol": row["atol"]}
    # evalplus: min(EVALPLUS_TIMEOUT_PER_TASK=60, sum of per-input limits) + 2
    timeout = min(60.0, 1.0 * len(inputs)) + 2.0 + 2.0
    try:
        r = subprocess.run([sys.executable, "-I", "-c", _EVALPLUS_RUNNER],
                           input=json.dumps(job), capture_output=True, text=True,
                           timeout=timeout)
    except Exception:
        return False
    try:
        d = json.loads(r.stdout.strip().splitlines()[-1])["details"]
    except Exception:
        return False
    return len(d) == len(inputs) and all(d)


def evalplus_pass(dataset, row, code):
    """HumanEval+ / MBPP+ pass@1 semantics: the base suite AND the plus suite."""
    return (_evalplus_check(dataset, row, code, row["base_input"])
            and _evalplus_check(dataset, row, code, row["plus_input"]))


def mbpp_plus_prompt(row):
    """The released MBPP+ prompt is a docstring holding the task text and ONE
    example assert; presented in the same shape as the sanitised-MBPP prompt
    above (task, the test to pass, and the code-block instruction), so the
    two MBPP variants differ only in their test suites."""
    body = row["prompt"].strip().strip('"').strip()
    lines = [l for l in body.splitlines() if l.strip()]
    asserts = [l for l in lines if l.lstrip().startswith("assert")]
    text = " ".join(l for l in lines if not l.lstrip().startswith("assert"))
    return (text + "\nYour code should pass these tests:\n\n" + "\n".join(asserts)
            + "\n\nReturn the complete solution in a ```python code block.")


# --------------------------------------------------------------------------
# LiveCodeBench (code_generation_lite v5+v6 slice, the OPD2 paper's own code
# benchmark).  Two problem kinds, told apart by the tests' `testtype`:
#   stdin      AtCoder-style: the program reads stdin and writes stdout; every
#              test is run as its own process with the test input on stdin.
#   functional LeetCode-style: `class Solution` with the method `fn_name`;
#              each test's input is one JSON value per line (the arguments),
#              its output the JSON of the expected return value.
# A problem passes only if every baked test passes (pass@1 per problem).
# Output comparison for stdin problems is WHITESPACE-INSENSITIVE and otherwise
# exact: the two outputs are split into whitespace-separated tokens (line
# breaks count as whitespace, so a k-lines answer printed on one line still
# passes) and compared token by token; a token pair that is not identical
# passes only if both parse as floats within 1e-6 (relative or absolute).
# Functional returns are compared structurally after tuples become lists,
# numbers within the same tolerance.  Per-test time limit 10 s, 4 GB.
_LCB_STDIN_FORMAT = (
    "### Format: Read the inputs from stdin solve the problem and write the answer "
    "to stdout (do not directly test on the sample inputs). Enclose your code within "
    "delimiters as follows. Ensure that when the python program runs, it reads the "
    "inputs, runs the algorithm and writes output to STDOUT.\n```python\n"
    "# YOUR CODE HERE\n```\n\n### Answer: (use the provided format with backticks)\n\n")
_LCB_FUNC_FORMAT = (
    "### Format: You will use the following starter code to write the solution to "
    "the problem and enclose your code within delimiters.\n```python\n{starter}\n```"
    "\n\n### Answer: (use the provided format with backticks)\n\n")
_LCB_TEST_TIMEOUT = 10.0
_LCB_LIMIT_PREFIX = ("import resource,sys\n"
                     "lim=4*1024**3\n"
                     "for r in (resource.RLIMIT_AS, resource.RLIMIT_DATA):\n"
                     "    try: resource.setrlimit(r, (lim, lim))\n"
                     "    except Exception: pass\n")
_LCB_FUNC_RUNNER = _LCB_LIMIT_PREFIX + r'''
import contextlib, io, json, signal
job = json.loads(sys.stdin.read())


class _T(Exception):
    pass


def _h(s, f):
    raise _T()


def norm(x):
    if isinstance(x, (list, tuple)):
        return [norm(i) for i in x]
    if isinstance(x, dict):
        return {str(k): norm(v) for k, v in x.items()}
    return x


def eq(a, b):
    if isinstance(a, list) and isinstance(b, list):
        return len(a) == len(b) and all(eq(x, y) for x, y in zip(a, b))
    if isinstance(a, dict) and isinstance(b, dict):
        return a.keys() == b.keys() and all(eq(a[k], b[k]) for k in a)
    if isinstance(a, bool) or isinstance(b, bool):
        return a == b
    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return abs(a - b) <= 1e-6 * max(1.0, abs(b))
    return a == b


res = []
try:
    g = {}
    sink = io.StringIO()
    with contextlib.redirect_stdout(sink), contextlib.redirect_stderr(sink):
        exec(job["code"], g)
        obj = g["Solution"]()
        fn = getattr(obj, job["fn_name"])
    for t in job["tests"]:
        ok = False
        try:
            args = [json.loads(l) for l in t["input"].split("\n") if l.strip()]
            exp = json.loads(t["output"])
            signal.signal(signal.SIGALRM, _h)
            signal.setitimer(signal.ITIMER_REAL, job["timeout"])
            try:
                with contextlib.redirect_stdout(sink), contextlib.redirect_stderr(sink):
                    out = fn(*args)
            finally:
                signal.setitimer(signal.ITIMER_REAL, 0)
            ok = eq(norm(out), norm(exp))
        except BaseException:
            ok = False
        res.append(bool(ok))
except BaseException:
    pass
sys.__stdout__.write(json.dumps(res))
'''


def lcb_prompt(row):
    if row["tests"][0]["testtype"] == "stdin":
        fmt = _LCB_STDIN_FORMAT
    else:
        fmt = _LCB_FUNC_FORMAT.format(starter=row["starter_code"].rstrip())
    return "### Question:\n" + row["question"].strip() + "\n\n" + fmt


_READS_STDIN = re.compile(r"input\s*\(|sys\.stdin|open\s*\(\s*0\s*\)|stdin")


def extract_program(text, stdin):
    """The program to run.  stdin problems: the LAST fenced block that reads
    standard input (a model that appends a demo block after its program does
    not lose the program), else the last block; functional problems: the same
    defining-block rule as MBPP (`class Solution` is a definition)."""
    if not stdin:
        return extract_code(text)
    blocks = CODE_BLOCK.findall(text or "")
    if not blocks:
        return text or ""
    readers = [b for b in blocks if _READS_STDIN.search(b)]
    return (readers or blocks)[-1]


def _float_tok(a, b):
    try:
        x, y = float(a), float(b)
    except ValueError:
        return False
    return abs(x - y) <= 1e-6 * max(1.0, abs(y))


def lcb_stdout_match(out, exp):
    a, b = (out or "").split(), (exp or "").split()
    if a == b:
        return True
    if len(a) != len(b):
        return False
    return all(x == y or _float_tok(x, y) for x, y in zip(a, b))


def _lcb_run_stdin(src, tests):
    with tempfile.NamedTemporaryFile("w", suffix=".py", delete=False) as f:
        f.write(src)
        path = f.name
    wrapper = _LCB_LIMIT_PREFIX + "import runpy\nrunpy.run_path(sys.argv[1], run_name='__main__')\n"

    def one(t):
        try:
            r = subprocess.run([sys.executable, "-I", "-c", wrapper, path],
                               input=t["input"], capture_output=True, text=True,
                               timeout=_LCB_TEST_TIMEOUT)
        except Exception:
            return False
        return r.returncode == 0 and lcb_stdout_match(r.stdout, t["output"])

    try:
        from concurrent.futures import ThreadPoolExecutor
        with ThreadPoolExecutor(min(8, len(tests))) as ex:
            return all(ex.map(one, tests))
    finally:
        try:
            os.unlink(path)
        except OSError:
            pass


def _lcb_run_functional(src, fn_name, tests):
    job = {"code": src, "fn_name": fn_name, "tests": tests, "timeout": _LCB_TEST_TIMEOUT}
    try:
        r = subprocess.run([sys.executable, "-I", "-c", _LCB_FUNC_RUNNER],
                           input=json.dumps(job), capture_output=True, text=True,
                           timeout=min(120.0, _LCB_TEST_TIMEOUT * len(tests)) + 5.0)
        res = json.loads(r.stdout.strip().splitlines()[-1])
    except Exception:
        return False
    return len(res) == len(tests) and all(res)


def lcb_pass(row, text):
    stdin = row["tests"][0]["testtype"] == "stdin"
    src = extract_program(text, stdin)
    if stdin:
        return _lcb_run_stdin(src, row["tests"])
    return _lcb_run_functional(src, row["fn_name"], row["tests"])


def build_prompts(bench, rows):
    out = []
    for r in rows:
        if bench in ("math500", "olympiadbench", "amc23"):
            out.append(r["problem"] + "\n\nPut your final answer within \\boxed{}.")
        elif bench == "lcb":
            out.append(lcb_prompt(r))
        elif bench in ("humaneval", "humaneval_plus"):
            out.append("Complete the following Python function. Return the complete "
                       "function in a ```python code block.\n\n```python\n"
                       + r["prompt"] + "```")
        elif bench == "mbpp":
            out.append(r["text"] + "\nYour code should pass these tests:\n\n"
                       + "\n".join(r["test_list"])
                       + "\n\nReturn the complete solution in a ```python code block.")
        elif bench == "mmlu_pro_sci":
            lines = "\n".join(f"{LETTERS[i]}. {o}" for i, o in enumerate(r["options"]))
            out.append(r["question"] + "\n\n" + lines +
                       "\n\nAnswer with the letter of the correct option inside \\boxed{}.")
        else:
            raise ValueError(bench)
    return out


def _grade_one(bench, r, t):
    if bench in ("math500", "olympiadbench", "amc23"):
        return bool(grade_math(extract_boxed(t), r["answer"]))
    if bench == "humaneval_plus":
        return evalplus_pass("humaneval", r, extract_code(t))
    if bench == "lcb":
        return lcb_pass(r, t)
    if bench == "humaneval":
        return run_python(extract_code(t) + "\n\n" + r["test"]
                          + f"\n\ncheck({r['entry_point']})\n")
    if bench == "mbpp":
        return run_python(extract_code(t) + "\n\n"
                          + "\n".join(r["test_list"]) + "\n")
    # multiple choice: the dataset's `answer` IS the option letter
    return extract_boxed(t).strip().upper()[:1] == str(r["answer"]).strip().upper()


_PROCESS_BOUND = ("humaneval", "mbpp", "humaneval_plus", "lcb")


def score(bench, rows, gens):
    """Per-prompt accuracy.  `gens[i]` is the list of samples for prompt i;
    the prompt's score is the mean correctness over its samples (avg@k), so a
    greedy benchmark (1 sample) reduces to pass@1.  The code graders run the
    program in a subprocess, so their prompts are graded 8 at a time (as in
    llm-opd-token-signal); the math graders stay sequential (math_verify's
    timeout is signal-based and only works in the main thread)."""
    def one(pair):
        r, samples = pair
        if not samples:
            return 0.0
        return sum(_grade_one(bench, r, t) for t in samples) / len(samples)

    if bench in _PROCESS_BOUND:
        from concurrent.futures import ThreadPoolExecutor
        with ThreadPoolExecutor(8) as ex:
            return list(ex.map(one, zip(rows, gens)))
    return [one(p) for p in zip(rows, gens)]


def generate_hf(model, tok, texts_in, max_new, n_samples, temperature, batch, label):
    """Fallback path: HF generate, left-padded batches.  Greedy when n_samples==1,
    else sampling with num_return_sequences (kept for completeness; the shipped
    image uses vLLM)."""
    gens, trunc, t0 = [], 0, time.time()
    do_sample = n_samples > 1 or temperature > 0
    for i in range(0, len(texts_in), batch):
        chunk = texts_in[i:i + batch]
        enc = tok(chunk, return_tensors="pt", padding=True, truncation=True,
                  max_length=2048, add_special_tokens=False).to("cuda")
        kw = dict(max_new_tokens=max_new)
        if do_sample:
            kw.update(do_sample=True, temperature=temperature, top_p=1.0,
                      num_return_sequences=n_samples)
        else:
            kw.update(do_sample=False, num_return_sequences=1)
        with torch.no_grad():
            gen = model.generate(**enc, **kw)
        plen = enc["input_ids"].shape[1]
        gen = gen.view(len(chunk), n_samples, -1)
        for j in range(len(chunk)):
            samples = []
            for s in range(n_samples):
                seq = gen[j, s, plen:]
                samples.append(tok.decode(seq, skip_special_tokens=True))
                if seq.shape[0] >= max_new:
                    trunc += 1
            gens.append(samples)
        print(f"[eval:{label}] {len(gens)}/{len(texts_in)}  {time.time() - t0:.0f}s",
              flush=True)
    return gens, trunc


def generate_vllm(llm, texts_in, max_new, n_samples, temperature, label):
    """Preferred path.  vLLM retires each sequence when it ends, so one rambling
    answer does not pace the batch.  Returns per-prompt lists of `n_samples`
    texts and the count of samples cut at the length cap."""
    from vllm import SamplingParams
    t0 = time.time()
    sp = SamplingParams(temperature=temperature, top_p=1.0, max_tokens=max_new,
                        n=n_samples, seed=0)
    outs = llm.generate(texts_in, sp)
    gens, trunc = [], 0
    for o in outs:
        samples = []
        for co in o.outputs:
            samples.append(co.text)
            if co.finish_reason == "length":
                trunc += 1
        gens.append(samples)
    print(f"[eval:{label}] {len(gens)}/{len(texts_in)}  {time.time() - t0:.0f}s",
          flush=True)
    return gens, trunc


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--model", required=True)
    ap.add_argument("--domain", required=True, choices=sorted(SETTINGS),
                    help="benchmark set: math / code / science")
    ap.add_argument("--label", default=None,
                    help="metric key prefix (the setting label); defaults to "
                         "--domain. Lets two settings on the same domain (e.g. "
                         "math and the capability-gap mathgap) emit distinct "
                         "metrics.")
    ap.add_argument("--max-new", type=int, default=4096,
                    help="per-token completion budget; the caller sets it to the "
                         "setting's training completion length.")
    ap.add_argument("--data-dir", default="/data/eval")
    ap.add_argument("--limit", type=int, default=0,
                    help="debug only: truncate each benchmark. NEVER used for a "
                         "leaderboard row.")
    ap.add_argument("--dump", default="",
                    help="optional directory: write <bench>.jsonl with every "
                         "prompt, generation and verdict (diagnostics only; the "
                         "scored line is unaffected)")
    args = ap.parse_args()

    from transformers import AutoModelForCausalLM, AutoTokenizer

    tok = AutoTokenizer.from_pretrained(args.model, padding_side="left")
    if tok.pad_token_id is None:
        tok.pad_token = tok.eos_token
    if tok.chat_template and NOTHINK_OLD in tok.chat_template:
        tok.chat_template = tok.chat_template.replace(NOTHINK_OLD, NOTHINK_NEW)
    tmpl = tok.chat_template or ""
    if "enable_thinking" in tmpl and "<think>" not in tmpl:
        # a hybrid (thinking-capable) model whose template we failed to pin
        print("ERROR chat template does not pin the no-think block; the student "
              "was distilled in no-think mode and must be scored in it",
              file=sys.stderr)
        return 1
    if "<think>" not in tmpl:
        # a non-hybrid model (e.g. the Qwen3-*-Instruct-2507 teacher): no thinking
        # switch exists, its native cue IS the no-think cue
        print("[eval] non-hybrid chat template (no thinking switch); native cue used",
              flush=True)

    use_vllm = False
    llm = model = None
    if os.environ.get("MLSB_EVAL_ENGINE", "auto") != "hf":
        try:
            from vllm import LLM
            ngpu = torch.cuda.device_count() or 1
            tp = 1
            while tp * 2 <= min(ngpu, 8):
                tp *= 2
            llm = LLM(model=args.model, tokenizer=args.model, dtype="bfloat16",
                      tensor_parallel_size=tp, gpu_memory_utilization=0.85,
                      max_model_len=max(8192, args.max_new + 2048),
                      disable_log_stats=True)
            use_vllm = True
            print(f"[eval] engine=vllm tp={tp} max_new={args.max_new}", flush=True)
        except Exception as exc:
            print(f"[eval] vLLM unavailable ({type(exc).__name__}: {exc}); "
                  "falling back to HF generate", flush=True)
    if not use_vllm:
        model = AutoModelForCausalLM.from_pretrained(
            args.model, torch_dtype=torch.bfloat16,
            attn_implementation="sdpa").cuda().eval()
        model.generation_config.pad_token_id = tok.pad_token_id
        print(f"[eval] engine=hf_generate max_new={args.max_new}", flush=True)

    label = args.label or args.domain
    per_bench = {}
    for bench, n_items, n_samples, temperature in SETTINGS[args.domain]:
        path = os.path.join(args.data_dir, bench + ".jsonl")
        if not os.path.exists(path):
            print(f"ERROR missing benchmark file {path}", file=sys.stderr)
            return 1
        rows = [json.loads(l) for l in open(path)]
        if n_items and len(rows) > n_items:
            stride = len(rows) // n_items
            rows = rows[::stride][:n_items]
        if args.limit:
            rows = rows[:args.limit]
        if not rows:
            print(f"ERROR benchmark {bench} is empty", file=sys.stderr)
            return 1
        texts_in = [tok.apply_chat_template(
            [{"role": "system", "content": SYSTEM_PROMPT},
             {"role": "user", "content": p}],
            tokenize=False, add_generation_prompt=True)
            for p in build_prompts(bench, rows)]
        if use_vllm:
            gens, trunc = generate_vllm(llm, texts_in, args.max_new, n_samples,
                                        temperature, bench)
        else:
            gens, trunc = generate_hf(model, tok, texts_in, args.max_new, n_samples,
                                      temperature, 48, bench)
        per_prompt = score(bench, rows, gens)
        if len(per_prompt) != len(rows):
            print(f"ERROR {bench}: scored {len(per_prompt)} of {len(rows)}",
                  file=sys.stderr)
            return 1
        if args.dump:
            os.makedirs(args.dump, exist_ok=True)
            with open(os.path.join(args.dump, bench + ".jsonl"), "w") as fh:
                for r, g, s in zip(rows, gens, per_prompt):
                    rr = {k: v for k, v in r.items() if k != "tests"} if bench == "lcb" else r
                    fh.write(json.dumps({"row": rr, "gens": g, "score": s}) + "\n")
        acc = sum(per_prompt) / len(per_prompt)
        total_samples = sum(len(g) for g in gens)
        per_bench[bench] = (acc, len(per_prompt), trunc, total_samples)
        print(f"[eval:{bench}] accuracy={acc:.4f} n={len(per_prompt)} "
              f"samples={total_samples} n_samples={n_samples} temp={temperature} "
              f"truncated={trunc}/{total_samples}", flush=True)

    if len(per_bench) != len(SETTINGS[args.domain]):
        print("ERROR not every benchmark produced a result", file=sys.stderr)
        return 1

    macro = sum(v[0] for v in per_bench.values()) / len(per_bench)
    # Macro under the setting LABEL (the scored key); per-benchmark diagnostics
    # namespaced by the label too, so two settings on the same domain do not
    # collide in the leaderboard row.  `_trunc` (the fraction of scored samples
    # that hit the completion cap) and the `_train_*` keys below are RECORDED,
    # NEVER SCORED -- score_spec reads only `<setting>_accuracy` -- so a reader can
    # tell a genuine accuracy difference from a truncation cliff.
    parts = [f"{label}_accuracy={macro:.6f}"]
    for b, (a, n, tr, ns) in per_bench.items():
        parts.append(f"{label}_{b}_accuracy={a:.6f}")
        parts.append(f"{label}_{b}_n={n}")
        parts.append(f"{label}_{b}_trunc={tr / max(ns, 1):.6f}")
    # Training-side diagnostics come from the file the FIXED driver wrote into the
    # checkpoint directory, not from the training log (which the editable recipe
    # shares a process with and could forge).
    stats_path = os.path.join(args.model, "train_stats.json")
    if os.path.exists(stats_path):
        try:
            with open(stats_path) as fh:
                st = json.load(fh)
            tot = max(int(st.get("rollouts_total", 0)), 1)
            parts.append(f"{label}_train_capped={int(st.get('rollouts_capped', 0)) / tot:.6f}")
            parts.append(f"{label}_train_gen_tokens={int(st.get('gen_tokens_used', 0))}")
        except Exception as exc:                       # diagnostics never fail a run
            print(f"[eval] train_stats.json unreadable ({type(exc).__name__}: {exc})", flush=True)
    print("EVAL_METRICS " + " ".join(parts), flush=True)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

