#!/usr/bin/env python3
"""Held-out evaluation for llm-distill-sgo-objective (VERIFIER ASSET, read-only).

Ported verbatim from the sibling task llm-opd-token-signal's scripts/eval_bench.py
(same prompts, no-think chat template, greedy decoding, graders and engine); only
the benchmark table below and the optional --dump differ.

Scores one setting's distilled student on that setting's held-out benchmarks
and prints exactly one authoritative line:

    EVAL_METRICS <label>_accuracy=<macro avg> <label>_<bench>_accuracy=<...> ...

This process never imports the editable module, so nothing a submission writes
can reach this stdout; the only channel from the submission to this script is
the checkpoint it produced, and `budget_check.py` asserts that the checkpoint is
still the declared student.

Nothing is printed if any benchmark fails to produce a result: an evaluation
that could not be run must not look like an evaluation that scored zero.

vLLM 0.12 (the image's engine) is preferred; HF `generate` with left padding is
the fallback when vLLM cannot be constructed (MLSB_EVAL_ENGINE=hf forces it).
Every benchmark is greedy (n=1, pass@1).  The per-token completion budget is
--max-new, which the caller sets to the setting's own training completion length
(so a model that learned to reason to 4096 is not truncated at eval); eval-time
truncation (finish_reason == length) is reported per benchmark.
"""
import argparse
import json
import os
import re
import subprocess
import sys
import tempfile
import time

import torch

SYSTEM_PROMPT = ("You are a helpful assistant. Solve the problem carefully and "
                 "provide a clear final answer.")

# naver-ai/opd2 opd_trainer.py:_NOTHINK_OLD_SNIPPET / _NOTHINK_NEW_SNIPPET --
# the same chat-template patch the trainer applies, so the model is evaluated
# in the mode it was distilled in.
NOTHINK_OLD = ("{%- if enable_thinking is defined and enable_thinking is false %}\n"
               "        {{- '<think>\\n\\n</think>\\n\\n' }}\n"
               "    {%- endif %}")
NOTHINK_NEW = "{{- '<think>\\n\\n</think>\\n\\n' }}"

# (benchmark, n_items, n_samples, temperature).  n_items = 0 keeps the whole
# benchmark; a positive value takes a deterministic STRIDE over it.  The
# per-token budget is the setting-wide --max-new (the setting's training
# completion), not a per-benchmark constant.  Keyed by DOMAIN (the benchmark
# set), not by the setting label: the two math settings (math @1.7B and the
# capability-gap mathgap @0.6B) share the math benchmarks but are told apart by
# the metric --label the caller passes.
#
# The benchmark set is the task brief's: MATH-500 + OlympiadBench for math,
# HumanEval + MBPP for code, all greedy pass@1 (the OPD2 paper's own math/code
# suites at their reduced-scale substitutes).  The setting macro is the
# unweighted mean over its benchmarks.
SETTINGS = {
    "math": [("math500", 0, 1, 0.0), ("olympiadbench", 0, 1, 0.0)],
    "code": [("lcb", 0, 1, 0.0), ("humaneval_plus", 0, 1, 0.0)],
    # the retired code pair (HumanEval + MBPP, near-saturated for a Qwen3-1.7B
    # student -- the 2026-09-23 setting audit); diagnostic only, NOT scored.
    "code_retired": [("humaneval", 0, 1, 0.0), ("mbpp", 0, 1, 0.0)],
}

_BOXED = re.compile(r"\\boxed\{((?:[^{}]|\{[^{}]*\})*)\}")
CODE_BLOCK = re.compile(r"```(?:python)?\n(.*?)```", re.S)
LETTERS = "ABCDEFGHIJ"


def extract_boxed(text):
    m = list(_BOXED.finditer(text or ""))
    if m:
        return m[-1].group(1).strip()
    t = (text or "").strip()
    if not t:
        return ""
    nums = re.findall(r"(-?\d+(?:\.\d+)?)", t.splitlines()[-1])
    return nums[-1] if nums else ""


def grade_math(pred, gold):
    if not pred:
        return False
    norm = lambda s: re.sub(r"[\s\\\$,]", "", str(s))
    if norm(pred) and norm(pred) == norm(gold):
        return True
    try:
        g = float(norm(gold))
        if abs(float(norm(pred)) - g) < 1e-4 * max(1.0, abs(g)):
            return True
    except Exception:
        pass
    try:
        from math_verify import parse as mvp, verify as mvv
        return bool(mvv(mvp(f"\\boxed{{{gold}}}"), mvp(f"\\boxed{{{pred}}}")))
    except Exception:
        return False


_DEFINES = re.compile(r"^\s*(def |class |import |from \S+ import )", re.M)


def extract_code(text):
    """The program to test: every fenced block that DEFINES something (functions,
    classes, imports), in order.  The sibling's version returned only the LAST
    block, which graded a model that writes its solution and then a separate
    `### Test Cases` block of asserts as the assert block alone (no function
    defined -> NameError -> fail): measured on untouched Qwen3-1.7B, 156 of its
    190 MBPP failures were exactly that (measured).  Blocks holding
    only asserts / prints are dropped; with no defining block the last block is
    used as before."""
    blocks = CODE_BLOCK.findall(text or "")
    if not blocks:
        return text or ""
    defs = [b for b in blocks if _DEFINES.search(b)]
    # an import-only block is not a solution on its own: if nothing kept defines a
    # function or class, grade every block together rather than imports + asserts
    if not defs or not any(re.search(r"^\s*(def |class )", b, re.M) for b in defs):
        return "\n\n".join(blocks)
    return "\n\n".join(defs)


def run_python(src, timeout=15):
    with tempfile.NamedTemporaryFile("w", suffix=".py", delete=False) as f:
        f.write(src)
        path = f.name
    try:
        r = subprocess.run([sys.executable, "-I", path], timeout=timeout,
                           stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        return r.returncode == 0
    except Exception:
        return False
    finally:
        try:
            os.unlink(path)
        except OSError:
            pass


# Ported verbatim from llm-opd-token-signal/scripts/eval_bench.py (2026-09-16, its
# measured): the EvalPlus and LiveCodeBench graders.
# --------------------------------------------------------------------------
# EvalPlus (HumanEval+ / MBPP+).  Ported from evalplus 0.3.1 (Apache-2.0):
# evalplus/eval/__init__.py (unsafe_execute + untrusted_check),
# evalplus/eval/_special_oracle.py and evalplus/data/mbpp.py
# (mbpp_deserialize_inputs).  The verifier does not import the package -- it
# drags in provider SDKs and fetches its data from GitHub on first use, which
# a compute node cannot do.  Semantics kept: expected outputs come from the
# canonical solution run on the same inputs in the same process; per-input
# time limit max(1 s, 4 x canonical time); exact match, with the atol / float
# rules and the per-task oracles; one isolated process per (problem, suite)
# under a 4 GB address-space limit, killed at min(60 s, sum of limits) + 2.
# The runner is a string executed with `python -I -c`, so nothing the graded
# program does can reach this process.
_EVALPLUS_RUNNER = r'''
import contextlib, io, json, math, resource, signal, sys
from copy import deepcopy

MBPP_OUTPUT_NOT_NONE_TASKS = ["check_str", "text_match_three", "text_starta_endb"]
MBPP_OUTPUT_SET_EQ_TASKS = ["similar_elements", "find_char_long", "common_in_nested_lists",
                            "extract_singly", "larg_nnum", "intersection_array",
                            "find_dissimilar", "Diff"]


def _surface_Area(base_edge, height):
    slant_height = math.sqrt((base_edge / 2) ** 2 + height ** 2)
    return round(base_edge ** 2 + 4 * (base_edge * slant_height) / 2)


def _digit_distance_nums(num1, num2):
    a, b = str(num1), str(num2)
    n = max(len(a), len(b))
    return sum(abs(int(x) - int(y)) for x, y in zip(a.zfill(n), b.zfill(n)))


def _poly(xs, x):
    return sum(c * math.pow(x, i) for i, c in enumerate(xs))


def mbpp_deserialize_inputs(task_id, inputs):
    task_id = int(task_id.split("/")[-1])
    if task_id in [2, 116, 132, 143, 222, 261, 273, 394, 399, 421, 424, 429, 470, 560,
                   579, 596, 616, 630, 726, 740, 744, 809]:
        return [[tuple(lst) for lst in inp] for inp in inputs]
    if task_id in [63, 64, 70, 94, 120, 237, 272, 299, 400, 409, 417, 438, 473, 614, 780]:
        return [[[tuple(lst) for lst in lst_lst] for lst_lst in inp] for inp in inputs]
    if task_id in [75, 413, 444, 753]:
        return [[[tuple(lst) for lst in inp[0]]] + [inp[1]] for inp in inputs]
    if task_id in (106, 750):
        return [[inp[0]] + [tuple(inp[1])] for inp in inputs]
    if task_id == 115:
        return [[[set(item) if isinstance(item, list) and len(item) else {}
                  for item in inp[0]]] for inp in inputs]
    if task_id == 124:
        return [(float(inp[0]), complex(inp[1])) for inp in inputs]
    if task_id in [250, 405, 446, 617, 720, 763, 808]:
        return [[tuple(inp[0])] + [inp[1]] for inp in inputs]
    if task_id in [259, 401, 445]:
        m = [[[tuple(lst) for lst in lst_lst] for lst_lst in inp] for inp in inputs]
        return [[tuple(lst) for lst in inp] for inp in m]
    if task_id == 278:
        m = [[[tuple(item) if isinstance(item, list) else item for item in inp[0]]]
             for inp in inputs]
        return [[tuple(lst) for lst in inp] for inp in m]
    if task_id == 307:
        return [[tuple(inp[0])] + [inp[1], inp[2]] for inp in inputs]
    if task_id == 722:
        return [[{k: tuple(v) for k, v in inp[0].items()}] + inp[1:] for inp in inputs]
    if task_id == 252:
        return [[complex(inp[0])] for inp in inputs]
    if task_id in [580, 615, 791]:
        def t(x):
            return tuple(t(i) for i in x) if isinstance(x, list) else x
        return [t(inp) for inp in inputs]
    return inputs


class _Timeout(Exception):
    pass


@contextlib.contextmanager
def time_limit(seconds):
    def handler(signum, frame):
        raise _Timeout()
    signal.setitimer(signal.ITIMER_REAL, seconds)
    signal.signal(signal.SIGALRM, handler)
    try:
        yield
    finally:
        signal.setitimer(signal.ITIMER_REAL, 0)


class _Sink(io.StringIO):
    def read(self, *a, **k):
        raise IOError
    readline = readlines = read


@contextlib.contextmanager
def swallow_io():
    s = _Sink()
    with contextlib.redirect_stdout(s), contextlib.redirect_stderr(s):
        old = sys.stdin
        sys.stdin = s
        try:
            yield
        finally:
            sys.stdin = old


def is_floats(x):
    if isinstance(x, float):
        return True
    if isinstance(x, (list, tuple)) and x:
        return all(isinstance(i, float) for i in x)
    return False


def allclose(a, b, rtol, atol):
    if isinstance(b, (list, tuple)):
        if len(a) != len(b):
            return False
        return all(allclose(x, y, rtol, atol) for x, y in zip(a, b))
    return abs(float(a) - float(b)) <= atol + rtol * abs(float(b))


def main():
    job = json.loads(sys.stdin.read())
    lim = 4 * 1024 ** 3
    for r in (resource.RLIMIT_AS, resource.RLIMIT_DATA, resource.RLIMIT_STACK):
        try:
            resource.setrlimit(r, (lim, lim))
