                    help="metric key prefix (the setting label); defaults to "
                         "--domain. Lets two settings on the same domain (e.g. "
                         "math and the capability-gap mathgap) emit distinct "
                         "metrics.")
    ap.add_argument("--max-new", type=int, default=4096,
                    help="per-token completion budget; the caller sets it to the "
                         "setting's training completion length.")
    ap.add_argument("--data-dir", default="/data/eval")
